sparql:
PREFIX pc: <https://example.org/productcatalog/>
SELECT DISTINCT ?product ?product_identifier ?properties ?manufacturer ?designation ?eclass_class ?eclass_irdi ?eclass_verification ?selection_status ?installation_verification ?family_range ?qudt_quantity_kind ?qudt_unit ?maximum_pressure ?qualification ?category ?disclaimer
WHERE {
  ?product pc:hasProductIdentifier ?product_identifier .
  FILTER(isLiteral(?product_identifier) && STR(?product_identifier) = "https://example.org/product-types/EandH_TMass_F300_Candidate")
  OPTIONAL { ?product pc:hasTechnicalProperties ?properties . }
  OPTIONAL { ?product pc:hasManufacturerName ?manufacturer . }
  OPTIONAL { ?product pc:hasManufacturerProductDesignation ?designation . }
  OPTIONAL { ?product pc:hasECLASSClass ?eclass_class . }
  OPTIONAL { ?product pc:hasECLASSIRDI ?eclass_irdi . }
  OPTIONAL { ?product pc:hasECLASSVerificationStatus ?eclass_verification . }
  OPTIONAL { ?product pc:hasSelectionStatus ?selection_status . }
  OPTIONAL { ?product pc:hasInstallationVerificationStatus ?installation_verification . }
  OPTIONAL { ?product pc:hasTechnicalProperties ?properties . ?properties pc:hasFamilyMeasuringRange ?family_range . }
  OPTIONAL { ?product pc:hasTechnicalProperties ?properties . ?properties pc:hasFamilyMeasuringRangeQUDTQuantityKind ?qudt_quantity_kind . }
  OPTIONAL { ?product pc:hasTechnicalProperties ?properties . ?properties pc:hasFamilyMeasuringRangeQUDTUnit ?qudt_unit . }
  OPTIONAL { ?product pc:hasTechnicalProperties ?properties . ?properties pc:hasFamilyMaximumProcessPressure ?maximum_pressure . }
  OPTIONAL { ?product pc:hasTechnicalProperties ?properties . ?properties pc:hasApplicationQualification ?qualification . }
  OPTIONAL { ?product pc:hasTechnicalProperties ?properties . ?properties pc:hasProductCategory ?category . }
  OPTIONAL { ?product pc:hasTechnicalProperties ?properties . ?properties pc:hasSelectionDisclaimer ?disclaimer . }
}
ORDER BY STR(?product)
